        int flips = 1;
        int first = p[0];
        if (p[first] != 0) {
            System.arraycopy(p, 0, pp, 0, pp.length);
            do {
                ++flips;
                for (int lo = 1, hi = first - 1; lo < hi; ++lo, --hi) {
                    int t = pp[lo]; pp[lo] = pp[hi]; pp[hi] = t;
                }
                int t = pp[first]; pp[first] = first; first = t;
            } while (pp[first] != 0);
        }
        return flips;
    }

    void runTask(int task) {
        int idxMin = task * CHUNKSZ;
        int idxMax = Math.min(Fact[n], idxMin + CHUNKSZ);
        firstPermutation(idxMin);
        int maxflips = 1;
        int chksum = 0;
        for (int i = idxMin; ; ) {
            if (p[0] != 0) {
                int flips = countFlips();
                if (flips > maxflips) maxflips = flips;
                chksum += (i & 1) == 0 ? flips : -flips;
