The program follows the classic fast Java approach used for this benchmark, with rows rendered in parallel.

**Pixel mapping and iteration**
- Each pixel maps to `Cr = 2x/N - 1.5` and `Ci = 2y/N - 1.0`.
- Iteration starts at `Z = C` and runs 49 more steps. This is the same as 50 iterations starting from `Z = 0`.
- A pixel counts as escaped once `|Z|² > 4`. Escape flags are set with OR, so later overflow to infinity or NaN cannot clear them.
- Bits are set for points that stay in the set, matching the reference PBM output.

**Speed**
- Pixels are computed in pairs, so two independent iteration chains run together.
- An 8-pixel byte stops early once all eight pixels have escaped.
- Rows are handed out to all available cores through an atomic row counter.

**Output**
- The header is `P4\nN N\n`, followed by all rows written at once from a single byte array.
- Padding bits past the image width are cleared to zero when N is not a multiple of 8.

```java
import java.io.*;
import java.util.concurrent.atomic.AtomicInteger;

public class mandelbrot {
    static double[] Crb, Cib;
    static byte[] out;
    static int N, rowBytes;
    static final AtomicInteger next = new AtomicInteger();

    static int getByte(int x, double Ci) {
        int res = 0;
        for (int i = 0; i < 8; i += 2) {
            double Cr1 = Crb[x + i], Cr2 = Crb[x + i + 1];
            double Zr1 = Cr1, Zi1 = Ci, Zr2 = Cr2, Zi2 = Ci;
            int b = 0;
            int j = 49;
            do {
                double nZr1 = Zr1 * Zr1 - Zi1 * Zi1 + Cr1;
                double nZi1 = 2.0 * Zr1 * Zi1 + Ci;
                Zr1 = nZr1; Zi1 = nZi1;
                double nZr2 = Zr2 * Zr2 - Zi2 * Zi2 + Cr2;
                double nZi2 = 2.0 * Zr2 * Zi2 + Ci;
                Zr2 = nZr2; Zi2 = nZi2;
                if (Zr1 * Zr1 + Zi1 * Zi1 > 4) { b |= 2; if (b == 3) break; }
                if (Zr2 * Zr2 + Zi2 * Zi2 > 4) { b |= 1; if (b == 3) break; }
            } while (--j > 0);
            res = (res << 2) + b;
        }
        return (~res) & 0xFF;
    }

    static void work() {
        int y;
        while ((y = next.getAndIncrement()) < N) {
            double Ci = Cib[y];
            int off = y * rowBytes;
            for (int xb = 0; xb < rowBytes; xb++) {
                out[off + xb] = (byte) getByte(xb * 8, Ci);
            }
            int rem = N & 7;
            if (rem != 0) {
                int mask = (0xFF << (8 - rem)) & 0xFF;
                out[off + rowBytes - 1] = (byte) (out[off + rowBytes - 1] & mask);
            }
        }
    }

    public static void main(String[] args) throws Exception {
        N = Integer.parseInt(args[0]);
        rowBytes = (N + 7) / 8;
        Crb = new double[rowBytes * 8 + 8];
        Cib = new double[N];
        double inv = 2.0 / N;
        for (int i = 0; i < Crb.length; i++) Crb[i] = i * inv - 1.5;
        for (int i = 0; i < N; i++) Cib[i] = i * inv - 1.0;
        out = new byte[rowBytes * N];

        int nt = Runtime.getRuntime().availableProcessors();
        Thread[] ts = new Thread[nt];
        for (int i = 0; i < nt; i++) {
            ts[i] = new Thread(mandelbrot::work);
            ts[i].start();
        }
        for (Thread t : ts) t.join();

        OutputStream os = new BufferedOutputStream(new FileOutputStream(FileDescriptor.out), 1 << 16);
        os.write(("P4\n" + N + " " + N + "\n").getBytes("US-ASCII"));
        os.write(out);
        os.flush();
    }
}
